#!/usr/bin/env bash
# اختبارات دخان للغة ألف، تعمل على لينكس وماك وويندوز (Git Bash).
#
# البناء وحده لا يكفي: العلل التي وجدناها - انهيار المفسّر عند رفع أي خطأ،
# وفشل استيراد اللواحق العربية - كلها تنجح في الترجمة وتظهر عند التشغيل فقط.
#
# الاستعمال: bash .github/scripts/smoke_test.sh <مسار مفسّر ألف>

set -u

if [ $# -lt 1 ]; then
	echo "الاستعمال: $0 <مسار مفسّر ألف>" >&2
	exit 2
fi

ALIF_REL="$1"
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
ALIF="$ROOT/$ALIF_REL"

if [ ! -x "$ALIF" ] && [ ! -f "$ALIF" ]; then
	echo "لم يُعثر على المفسّر: $ALIF" >&2
	exit 2
fi

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

fails=0
pass() { echo "  [ناجح] $1"; }
fail() { echo "  [فاشل] $1"; fails=$((fails + 1)); }

# إدخال سخي يكفي الأمثلة التفاعلية (عدد للأولية، وحركات للعبة XO)
FEED="30@4@0@8@2@6@1@3@5@7@"
FEED="$(printf '%s' "$FEED" | tr '@' '\n')"

echo "== المفسّر: $ALIF"
echo

# ------------------------------------------------------------------
echo "== 1. تشغيل كل الأمثلة"
cd "$ROOT/examples" || exit 2

# نقتصر على الأمثلة المتعقَّبة في git: تشغيل Status.الف ينشئ ملف_تجريبي.الف
# وهو ملف بيانات لا برنامج، فلو أخذناه بمحرف البدل لفشل في الجولة التالية.
EXAMPLES="$(cd "$ROOT" && git -c core.quotepath=false ls-files "examples/*.الف" 2>/dev/null | sed 's|^examples/||')"
[ -n "$EXAMPLES" ] || EXAMPLES="$(ls *.الف 2>/dev/null)"

echo "$EXAMPLES" | while IFS= read -r f; do
	[ -n "$f" ] && [ -e "$f" ] || continue
	printf '%s' "$FEED" | "$ALIF" "$f" > "$TMP/out.txt" 2>&1
	rc=$?
	if [ $rc -eq 0 ]; then
		pass "$f"
	else
		fail "$f (رمز الخروج $rc)"
		tail -5 "$TMP/out.txt"
		echo x >> "$TMP/failed"
	fi
done
[ -f "$TMP/failed" ] && fails=$((fails + $(wc -l < "$TMP/failed")))
rm -f "$ROOT/examples/ملف_تجريبي.الف"
echo

# ------------------------------------------------------------------
# انحدار: كان رفع أي خطأ يقرأ ذاكرة محررة فينهار المفسّر بلا رسالة.
# المطلوب رمز خروج 1 مع تتبّع عكسي، لا انهيار (139 أو 3221225477).
echo "== 2. الخطأ يُطبع ولا يُسقط المفسّر"
printf 'اطبع(1 + "ن")\n' > "$TMP/خطأ.الف"
"$ALIF" "$TMP/خطأ.الف" > "$TMP/out.txt" 2>&1
rc=$?
if [ $rc -eq 1 ] && grep -q "خطأ_نوع" "$TMP/out.txt"; then
	pass "خطأ_نوع مع تتبّع عكسي"
else
	fail "رمز الخروج $rc (المتوقع 1)"
	cat "$TMP/out.txt"
fi
echo

# ------------------------------------------------------------------
# انحدار: التكرار على مصفوفة ينتهي برفع خطأ_مؤشر داخلياً، وهو ما كان
# يفجّر العلة السابقة. هذا ما أوقف لعبة XO.
echo "== 3. التكرار على مصفوفة"
printf 'ت = [1, 2, 3]\nلكل ش في ت:\n	اطبع(ش)\n' > "$TMP/تكرار.الف"
"$ALIF" "$TMP/تكرار.الف" > "$TMP/out.txt" 2>&1
rc=$?
if [ $rc -eq 0 ] && grep -q "3" "$TMP/out.txt"; then
	pass "المصفوفة تُكرَّر حتى نهايتها"
else
	fail "رمز الخروج $rc"
	cat "$TMP/out.txt"
fi
echo

# ------------------------------------------------------------------
echo "== 4. تشغيل ملف بلاحقة .مكتبة"
cd "$ROOT/examples" || exit 2
"$ALIF" "مثال.مكتبة" > "$TMP/out.txt" 2>&1
rc=$?
if [ $rc -eq 0 ]; then
	pass "مثال.مكتبة"
else
	fail "مثال.مكتبة (رمز الخروج $rc)"
	cat "$TMP/out.txt"
fi
echo

# ------------------------------------------------------------------
# يستورد وحدة بلاحقة .مكتبة، وحزمة يعرّفها __تهيئة__.مكتبة
echo "== 5. استيراد الوحدات والحزم بلاحقة عربية"
printf 'من مثال استورد ترحيب\nاستورد مكتبة\n' > "استيراد_مؤقت.الف"
"$ALIF" "استيراد_مؤقت.الف" > "$TMP/out.txt" 2>&1
rc=$?
rm -f "استيراد_مؤقت.الف"
if [ $rc -eq 0 ]; then
	pass "استيراد .مكتبة و __تهيئة__.مكتبة"
else
	fail "الاستيراد فشل (رمز الخروج $rc)"
	cat "$TMP/out.txt"
fi
echo

# ------------------------------------------------------------------
echo "== 6. رفض اللاحقة غير المعتمدة"
printf 'اطبع(1)\n' > "$TMP/ملف.txt"
"$ALIF" "$TMP/ملف.txt" > "$TMP/out.txt" 2>&1
if grep -q "لاحقة الملف" "$TMP/out.txt"; then
	pass "رُفض .txt برسالة عربية"
else
	fail "لم تظهر رسالة اللاحقة"
	cat "$TMP/out.txt"
fi
echo

# ------------------------------------------------------------------
if [ $fails -eq 0 ]; then
	echo "== كل الاختبارات ناجحة"
	exit 0
fi
echo "== عدد الاختبارات الفاشلة: $fails"
exit 1
